// ProcResult.java — the OUT status + optional message
package com.nbi.db;

public class ProcResult {
    public final String status;   // "SUCCESS" / "FAILED_*"
    public final String message;
    public ProcResult(String status, String message) { this.status = status; this.message = message; }
    public String toString() { return status + (message == null ? "" : " (" + message + ")"); }
}
