// ApplyRateProc.java — the stored procedure simulated in Java
package com.nbi.db;

import java.util.Map;

public class ApplyRateProc {
    private final Map<String,Double> productRates;      // source table: product_rates
    private final Map<String,Double> accountInterest;   // target table: account_interest

    public ApplyRateProc(Map<String,Double> productRates, Map<String,Double> accountInterest) {
        this.productRates = productRates;
        this.accountInterest = accountInterest;
    }

    /* Engine-specific equivalent (PL/pgSQL):
       CREATE PROCEDURE apply_rate(IN p_account TEXT, IN p_product TEXT, OUT p_status TEXT)
       LANGUAGE plpgsql AS $$
       DECLARE v_rate NUMERIC;              -- local variable
       BEGIN
         -- SELECT ... INTO: fetch one value using the two inputs in WHERE
         SELECT rate INTO STRICT v_rate FROM product_rates WHERE product = p_product;
         -- dependent UPDATE on the THIRD table using the fetched value
         UPDATE account_interest SET rate = v_rate WHERE account = p_account;
         IF NOT FOUND THEN RAISE EXCEPTION 'account not updated'; END IF;
         p_status := 'SUCCESS';             -- OUT status
       EXCEPTION
         WHEN NO_DATA_FOUND THEN p_status := 'FAILED_UNKNOWN_PRODUCT'; -- rollback implicit
         WHEN OTHERS       THEN p_status := 'FAILED_' || SQLERRM;
       END; $$;
    */
    public ProcResult call(String pAccount, String pProduct) {
        // --- begin transaction (snapshot target for rollback) ---
        Double backup = accountInterest.get(pAccount);
        try {
            // SELECT rate INTO v_rate FROM product_rates WHERE product = p_product;
            Double vRate = productRates.get(pProduct);
            if (vRate == null) {                       // NO_DATA_FOUND
                throw new IllegalStateException("UNKNOWN_PRODUCT");
            }
            // UPDATE account_interest SET rate = v_rate WHERE account = p_account;
            if (!accountInterest.containsKey(pAccount)) { // @@ROWCOUNT == 0
                throw new IllegalStateException("ACCOUNT_NOT_UPDATED");
            }
            accountInterest.put(pAccount, vRate);
            // --- commit ---
            return new ProcResult("SUCCESS", "rate " + vRate + " applied to " + pAccount);
        } catch (IllegalStateException e) {
            // --- rollback: restore target so no partial change persists ---
            if (backup != null) accountInterest.put(pAccount, backup);
            return new ProcResult("FAILED_" + e.getMessage(), null);
        }
    }
}
