// Demo.java — CALL apply_rate(...) for success and failure cases
package com.nbi.db;

import java.util.*;

public class Demo {
    public static void main(String[] args) {
        Map<String,Double> productRates = Map.of("SAV", 3.5, "FD", 6.75);
        Map<String,Double> accountInterest = new HashMap<>(Map.of("A100", 0.0, "A200", 0.0));

        ApplyRateProc proc = new ApplyRateProc(productRates, accountInterest);

        // CALL apply_rate('A100','FD', @status);
        System.out.println("Call 1 (A100, FD):      " + proc.call("A100", "FD"));
        // Unknown product -> rollback, failure status
        System.out.println("Call 2 (A200, LOAN):    " + proc.call("A200", "LOAN"));
        // Unknown account -> rollback, failure status
        System.out.println("Call 3 (A999, SAV):     " + proc.call("A999", "SAV"));

        System.out.println("Final account_interest: " + accountInterest);
    }
}
